;; Regenerate src/vendor/bearssl/roots.c from mozilla-roots.pem.
;;
;; Usage: ./mino src/vendor/bearssl/tools/gen_ca_roots.clj
;;
;; Decodes each PEM CERTIFICATE block to DER here, at generation time,
;; and emits one concatenated DER blob plus a {pointer, length} anchor
;; table over it. The TLS certificate validator consumes the table
;; directly; nothing decodes PEM at runtime. Deterministic: input
;; order, no timestamps.
;;
;; The PEM is Mozilla root store data (copyright Mozilla Foundation,
;; MPL-2.0) as republished by curl at https://curl.se/ca/cacert.pem;
;; the generated headers carry that attribution and the full license
;; text lives in src/vendor/bearssl/MPL-2.0.txt.

(require '[clojure.string :as str])

(def pem-path "src/vendor/bearssl/mozilla-roots.pem")
(def out-path "src/vendor/bearssl/roots.c")
(def hdr-path "src/vendor/bearssl/roots.h")

(def pem (slurp pem-path))

(def date-line
  (or (first (filter #(str/includes? % "Certificate data from Mozilla as of:")
                     (str/split-lines pem)))
      (throw (ex-info "mozilla-roots.pem: missing Mozilla date header" {}))))

(defn- pem-blocks
  "Split a PEM file into base64 bodies of CERTIFICATE blocks."
  [text]
  (loop [lines (str/split-lines text) acc [] body nil]
    (if (empty? lines)
      (if body
        (throw (ex-info "mozilla-roots.pem: unterminated CERTIFICATE block" {}))
        acc)
      (let [line (first lines)]
        (cond
          (str/starts-with? line "-----BEGIN CERTIFICATE-----")
          (recur (rest lines) acc [])

          (str/starts-with? line "-----END CERTIFICATE-----")
          (if (nil? body)
            (throw (ex-info "mozilla-roots.pem: END without BEGIN" {}))
            (recur (rest lines) (conj acc (str/join body)) nil))

          (some? body)
          (recur (rest lines) acc (conj body line))

          :else
          (recur (rest lines) acc body))))))

(def blocks (pem-blocks pem))

(when (empty? blocks)
  (throw (ex-info "mozilla-roots.pem: no CERTIFICATE blocks" {})))

;; Decode to DER and flatten into one blob, tracking offsets.
(def anchors
  (loop [blocks blocks offset 0 acc []]
    (if (empty? blocks)
      acc
      (let [der (base64-decode (first blocks))
            len (count der)]
        (when (and (pos? len) (not= 0x30 (nth der 0)))
          (throw (ex-info "DER does not start with a SEQUENCE tag" {:offset offset})))
        (recur (rest blocks) (+ offset len)
               (conj acc {:offset offset :len len :der der}))))))

(def blob
  (into [] (mapcat (fn [a] (map #(nth (:der a) %) (range (:len a))))) anchors))

(defn- hex2 [b] (format "0x%02x" b))

(def blob-lines
  (loop [i 0 acc []]
    (if (>= i (count blob))
      acc
      (let [chunk (subvec blob i (min (+ i 16) (count blob)))]
        (recur (+ i 16)
               (conj acc (str "    " (str/join "," (map hex2 chunk)) ",")))))))

(def table-lines
  (map (fn [a] (str "    { mino_ca_der_data + " (:offset a) ", " (:len a) " },"))
       anchors))

(def text
  (str "/* Mozilla CA root certificates as DER data. Generated by\n"
       " * src/vendor/bearssl/tools/gen_ca_roots.clj from\n"
       " * src/vendor/bearssl/mozilla-roots.pem; do not edit by hand.\n"
       " *\n"
       " * Certificate data copyright Mozilla Foundation and\n"
       " * individual contributors, distributed under the Mozilla\n"
       " * Public License 2.0 (https://mozilla.org/MPL/2.0/). The\n"
       " * bundle is Mozilla's root store as republished by curl:\n"
       " * https://curl.se/ca/cacert.pem.\n"
       " *\n"
       " * " date-line "\n"
       " * PEM sha256: " (sha256 pem) "\n"
       " * " (count anchors) " anchors, " (count blob) " bytes of DER.\n"
       " *\n"
       " * Update ritual: fetch https://curl.se/ca/cacert.pem over the\n"
       " * checked-in PEM, rerun the generator, commit both, and update\n"
       " * the README (sha256 and Mozilla date line).\n"
       " */\n"
       "#include \"roots.h\"\n\n"
       "/* Concatenated DER certificates; anchor i spans\n"
       " * mino_ca_der_data[offset_i, offset_i + len_i).\n"
       " */\n"
       "const unsigned char mino_ca_der_data[] = {\n"
       (str/join "\n" blob-lines) "\n"
       "};\n\n"
       "/* DER {pointer, length} pairs, one per root certificate,\n"
       " * in PEM order.\n"
       " */\n"
       "const mino_ca_anchor mino_ca_anchors[] = {\n"
       (str/join "\n" table-lines) "\n"
       "};\n\n"
       "const size_t mino_ca_anchor_count = " (count anchors) ";\n"))

(def mozilla-date
  (str/replace date-line "## Certificate data from Mozilla as of: "
               "Mozilla data as of: "))

(def hdr-text
  (str "/* Declarations for the generated Mozilla CA root snapshot.\n"
       " * Generated by src/vendor/bearssl/tools/gen_ca_roots.clj\n"
       " * alongside roots.c; do not edit by hand.\n"
       " *\n"
       " * Certificate data copyright Mozilla Foundation and\n"
       " * contributors, MPL-2.0 (https://mozilla.org/MPL/2.0/), via\n"
       " * https://curl.se/ca/cacert.pem; " mozilla-date ".\n"
       " */\n"
       "#ifndef MINO_CA_ROOTS_H\n"
       "#define MINO_CA_ROOTS_H\n\n"
       "#include <stddef.h>\n\n"
       "typedef struct mino_ca_anchor {\n"
       "    const unsigned char *der;\n"
       "    size_t len;\n"
       "} mino_ca_anchor;\n\n"
       "extern const unsigned char mino_ca_der_data[];\n"
       "extern const mino_ca_anchor mino_ca_anchors[];\n"
       "extern const size_t mino_ca_anchor_count;\n\n"
       "#endif /* MINO_CA_ROOTS_H */\n"))

(spit out-path text)
(spit hdr-path hdr-text)
(println "gen-ca-roots:" out-path)
(println "  mozilla date line:" date-line)
(println "  pem sha256:" (sha256 pem))
(println "  anchors:" (count anchors) "der bytes:" (count blob))
